SELECT jsonb_build_object('database',current_database(),'user',current_user,
'role',(SELECT jsonb_build_object('name',rolname,'superuser',rolsuper,'inherit',rolinherit,'create_role',rolcreaterole,'create_db',rolcreatedb,'bypass_rls',rolbypassrls,'login',rolcanlogin) FROM pg_roles WHERE rolname=current_user),
'memberships',(SELECT coalesce(jsonb_agg(jsonb_build_object('member',u.rolname,'role',g.rolname)),'[]') FROM pg_auth_members a JOIN pg_roles u ON u.oid=a.member JOIN pg_roles g ON g.oid=a.roleid WHERE u.rolname=current_user),
'objects',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'select',has_table_privilege(current_user,c.oid,'SELECT'),'insert',has_table_privilege(current_user,c.oid,'INSERT'),'update',has_table_privilege(current_user,c.oid,'UPDATE'),'delete',has_table_privilege(current_user,c.oid,'DELETE'),'schema_usage',has_schema_privilege(current_user,n.oid,'USAGE'),'schema_create',has_schema_privilege(current_user,n.oid,'CREATE')) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','dim','cfg','bank_knowledge','bank_knowledge_new_bank') AND c.relkind='r'))